{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Methoxsalen, a furanocoumarin sharing the coumarin lactone core, has relatively low systemic bioavailability in humans at doses up to 10 mg, supporting a low-F prediction for the coumarin query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Chrysin, a benzopyrone flavonoid, has an estimated oral bioavailability of only 0.003–0.02% in healthy volunteers after a 400 mg oral dose, demonstrating very low systemic availability for a related benzopyrone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Baicalein, another benzopyrone flavonoid, is clinically limited by low oral bioavailability in humans, supporting the pattern of low systemic F for coumarin-like benzopyrones.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Anthocyanins, which contain a benzopyrylium core, have oral bioavailability estimated at less than 1–2% in humans, further supporting low systemic availability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Zonisamide, a benzisoxazole, has virtually complete oral bioavailability in humans; this is contradictory to a low-F prediction but has low structural transferability to the coumarin query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is coumarin, a small lipophilic lactone that is likely well absorbed but subject to extensive first-pass metabolism, keeping systemic F below 20%. The closest analogue, methoxsalen, shows relatively low human systemic availability, and several benzopyrone flavonoids show very low oral F. High-F drugs in the evidence set are structurally distant and do not override the coumarin-specific low-bioavailability pattern.",
  "evidence_gaps": [
    "No direct quantitative absolute oral bioavailability measurement for coumarin itself is present in the evidence set.",
    "The methoxsalen record is qualitative ('relatively low') and does not specify whether F is below the 20% threshold.",
    "Most low-F analogues are more polar flavonoids with different metabolic pathways, limiting quantitative transferability to coumarin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

